def diff_even_odd(list1):
    # Initialize variables to store the first even and odd numbers
    first_even = None
    first_odd = None

    # Iterate through the list to find the first even and odd numbers
    for num in list1:
        if num % 2 == 0:
            if first_even is None or num < first_even:
                first_even = num
        else:
            if first_odd is None or num > first_odd:
                first_odd = num

    # Calculate the difference between the first even and odd numbers
    if first_even is not None and first_odd is not None:
        return first_odd - first_even
    else:
        return None
